SELECT r.id, r.shareable, r.summary, r.last_activity, r.usage_input_tokens, r.usage_output_tokens, r.usage_embedding_tokens, r.created_at, r.updated_at, r.created_by_user_id, r.agent_id, r.default_model_provider, r.default_model, r.default_model_params, r.title, r.conversation_parent_id, r.conversation_parent_turn_id, r.metadata, r.visibility, r.status, r.scheduled, r.schedule_id, r.schedule_run_id, r.schedule_kind, r.schedule_timezone, r.schedule_cron_expr, r.external_task_ref FROM (SELECT t.* FROM  (SELECT c.* , 0 AS should_delete FROM conversation c)  t) r WHERE $criteria.CompositeIn("r", $WriterKeys)